svg.script:
var bg=document.getElementById("bg");
var g=document.getElementById("tree-g");
var px=0,py=0,dr=0,sx,sy;
bg.addEventListener("mousedown",function(e){if(e.target!==bg)return;dr=1;sx=e.clientX-px;sy=e.clientY-py;bg.style.cursor="grabbing";});
document.addEventListener("mousemove",function(e){if(!dr)return;px=e.clientX-sx;py=e.clientY-sy;var z=g.getAttribute("data-zoom")||1;g.setAttribute("transform","translate("+px+","+py+") scale("+z+")");});
document.addEventListener("mouseup",function(){dr=0;bg.style.cursor="default";});
bg.addEventListener("wheel",function(e){e.preventDefault();var z=parseFloat(g.getAttribute("data-zoom")||1);z+=e.deltaY>0?-0.1:0.1;z=Math.max(0.3,Math.min(3,z));g.setAttribute("data-zoom",z);g.setAttribute("transform","translate("+px+","+py+") scale("+z+")");});
